#include "ui.h"
#define STB_IMAGE_WRITE_IMPLEMENTATION
#include <stb/stb_image_write.h>
int main(int argc,char**argv){UI ui("assets","build");if(argc>1&&std::string(argv[1])=="details")ui.action(CONFIRM);if(argc>1&&std::string(argv[1])=="search")ui.action(SEARCH);if(argc>1&&std::string(argv[1])=="downloads"){ui.tab=3;ui.serviceStatus="Background service connected (preview)";DownloadRow j;j.id=1;j.title="Generated sample / sample.torrent";j.phase="Downloading";j.state=DownloadState::Active;j.done=34000000;j.total=100000000;j.rate=2500000;j.peers=1;ui.jobs.push_back(j);}if(argc>1&&std::string(argv[1])=="install"){ui.tab=3;ui.installPicker=true;InstallPackage p;p.jobId=1;p.name="Generated sample - base.pkg";p.titleId="TEST00001";p.bytes=100000000;p.note="Ready to install";ui.packages.push_back(p);}if(argc>1&&std::string(argv[1])=="service"){ui.tab=3;ui.servicePicker=true;ui.serviceStatus="In-app downloads | Keep NULL_store open.";}if(argc>1&&std::string(argv[1])=="sources")ui.sourceFilterPicker=true;ui.draw();std::vector<unsigned char>rgb(1920*1080*3);for(size_t i=0;i<ui.c.pixels.size();++i){auto p=ui.c.pixels[i];rgb[i*3]=p>>16;rgb[i*3+1]=p>>8;rgb[i*3+2]=p;}std::string out=argc>1?std::string("build/preview-")+argv[1]+".png":"build/preview.png";return stbi_write_png(out.c_str(),1920,1080,3,rgb.data(),0)?0:1;}
